INSERT INTO zhishi_notices (id, real, source, publish_date, title, event, audience, deadline, countdown, materials, entry, confidence, priority, points, digest_one, digest_points, raw, url, site, unit, src_generated_at) VALUES ('ahau-006', TRUE, '工学院', '2026-10-21', '关于开展2026年秋季学期“匠心铸魂·党员先行”携手成长学生寝室优秀微事迹评选活动的通知2026-10-21', '学工事务', NULL, NULL, NULL, NULL, NULL, 0.5, 'medium', '[{"text": "各党支部、全体结对党员： 为进一步强化党员责任意识，提升帮扶质量，树立先进典型，推广暖心帮扶经验，激", "quote": "各党支部、全体结对党员： 为进一步强化党员责任意识，提升帮扶质量，树立先进典型，推广暖心帮扶经验，激"}]'::jsonb, '学工事务：关于开展2026年秋季学期“匠心铸魂·党员先行”携手成长学生寝室优秀微事迹评选活', '[{"text": "各党支部、全体结对党员： 为进一步强化党员责任意识，提升帮扶质量，树立先进典型，推广暖心帮扶经验，激", "quote": "各党支部、全体结对党员： 为进一步强化党员责任意识，提升帮扶质量，树立先进典型，推广暖心帮扶经验，激"}]'::jsonb, '各党支部、全体结对党员： 为进一步强化党员责任意识，提升帮扶质量，树立先进典型，推广暖心帮扶经验，激发党员 “比学赶超”的热情，确保携手成长工作走深走实，学院党委决定开展2026年 秋 季学期 “匠心铸魂·党员先行”携手成长学生寝室优秀微事迹评选活动。现将有关事项通知如下： 一、参与对象 全体参与携手成长结对帮扶的教职工党员和学生党员。 二、评选要求 1.材料内容 每位结对党员需提交 500-1000字左右的事迹介绍，围绕《机械与车辆工程学院“匠心铸魂·党员先行”携手成长学生寝室实施方案》中“生活护航、学业领航、职', 'https://gxy.ahau.edu.cn/info/1143/43801.htm', '工学院 · 通知公告', 'gxy', '2026-11-04 13:33:17') ON CONFLICT (id) DO UPDATE SET source=EXCLUDED.source, publish_date=EXCLUDED.publish_date, title=EXCLUDED.title, event=EXCLUDED.event, deadline=EXCLUDED.deadline, points=EXCLUDED.points, digest_one=EXCLUDED.digest_one, digest_points=EXCLUDED.digest_points, raw=EXCLUDED.raw, url=EXCLUDED.url, site=EXCLUDED.site, unit=EXCLUDED.unit, src_generated_at=EXCLUDED.src_generated_at